def compute(vars):
    statutory_rate = vars["v1"]
    effective_rate = vars["v2"]
    difference = statutory_rate - effective_rate

    return {
        "value": difference,
        "trace": {
            "statutory_rate": statutory_rate,
            "effective_rate": effective_rate,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
